using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace VinsPDF {
internal static class Version027Tests {
 static void Assert(bool pass,string message){if(!pass)throw new Exception(message);}
 public static int Run(string[] args){string dir=args[1];Directory.CreateDirectory(dir);try{using(var e=new PdfEngine()){e.Open(args[2]);using(var a=e.Preview(0,0,1000))using(var b=e.Preview(0,0,1000)){Assert(e.CacheHits>0,"Cache miss on revisit");for(int y=0;y<a.Height;y+=7)for(int x=0;x<a.Width;x+=7)Assert(a.GetPixel(x,y)==b.GetPixel(x,y),"Cache changed pixels");}
 int id=e.PutTextBlock(0,new int[0],"Colour and alignment\nShort",new TextStyle{Size=18,Ink=Color.DarkRed,Alignment=2,BoxWidth=250},new PointF(.12f,.3f));var text=e.GetObjects(0).Objects.Where(o=>o.Text=="Colour and alignment"||o.Text=="Short").ToArray();Assert(text.Length==2&&text.All(o=>(o.Color&0xffffff)==0x8b0000),"Text colour failed");Assert(text.First(o=>o.Text=="Short").Bounds.Left>text.First(o=>o.Text=="Colour and alignment").Bounds.Left,"Right alignment failed");e.AssignLayer(0,text.Select(o=>o.Id).ToArray(),"Notes");e.LockLayer(0,"Notes",true);Assert(e.GetObjects(0).Objects.Where(o=>o.Layer=="Notes").All(o=>o.Locked),"Layer lock failed");e.ShowLayer(0,"Notes",false);Assert(!e.GetObjects(0).Objects.Any(o=>o.Layer=="Notes"),"Layer hide failed");e.ShowLayer(0,"Notes",true);Assert(e.GetObjects(0).Objects.Count(o=>o.Layer=="Notes")==2,"Layer show lost items");int hits=e.CacheHits;using(var image=e.Preview(0,0,1000))image.Save(Path.Combine(dir,"styled.png"));Assert(e.CacheHits==hits,"Stale render after editing");
 using(var printImage=new Bitmap(850,1100))using(var graphics=Graphics.FromImage(printImage)){graphics.Clear(Color.White);var printArgs=new System.Drawing.Printing.PrintPageEventArgs(graphics,new Rectangle(50,50,750,1000),new Rectangle(0,0,850,1100),new System.Drawing.Printing.PageSettings());e.PaintPrintPage(0,printArgs);printImage.Save(Path.Combine(dir,"print-render.png"));}
 e.ExportCopy(Path.Combine(dir,"export.pdf"));e.ExportPages(Path.Combine(dir,"reordered.pdf"),new[]{1,0},new[]{1,0});e.ExportReduced(Path.Combine(dir,"reduced.pdf"),120);e.Combine(Path.Combine(dir,"combined.pdf"),new[]{args[2],args[2]});e.SaveCopy(Path.Combine(dir,"saved.pdf"));Assert(e.GetObjects(0).Objects.Count(o=>o.Layer=="Notes")==2,"Layer names not saved");using(var b=e.Preview(0,0,1000))b.Save(Path.Combine(dir,"styled-reopened.png"));e.Open(Path.Combine(dir,"combined.pdf"));Assert(e.Count==4,"Combine wrong count");e.Open(Path.Combine(dir,"reordered.pdf"));Assert(e.Count==2&&e.Sizes[0].Width>e.Sizes[0].Height,"Page rotation/reorder failed");e.Open(Path.Combine(dir,"reduced.pdf"));Assert(e.Count==2&&e.GetObjects(0).Objects.All(o=>o.Kind==3),"Reduced export not image PDF");Assert(PdfEngine.PageRange("2,1-2",2).SequenceEqual(new[]{1,0,1}),"Page range order failed");}
 Assert(RenderCache.Bytes==0,"Cache survived document disposal");File.WriteAllText(Path.Combine(dir,"engine-027.txt"),"PASS cache pixels/invalidation/disposal, colour/alignment, named layers hide/show/lock/save, export, reduced JPEG PDF, extract/reorder/rotate, combine and ordered page ranges.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"engine-027.txt"),"FAIL "+ex);return 1;}}
}
internal sealed partial class MainForm {
 public static string V027Directory;static bool V027Started;
 void Start027Test(){int stage=0,ticks=0;Rectangle camera=Rectangle.Empty;TabWindow shell=TopLevelControl as TabWindow;var timer=new Timer{Interval=170};timer.Tick+=delegate{if(++ticks>1800){Trace("FAIL 027 timeout stage="+stage);timer.Stop();return;}if(editBusy||lastRenderedVersion!=viewVersion||(stage==1&&secondRenderedVersion!=secondVersion))return;if(stage==8&&overview!=null&&!overview.IsDisposed&&overview.Grid.ReadyCount<Math.Min(15,sizes.Length))return;try{switch(stage++){
 case 0:SetTwoPages(true);rotateAll=true;Rotate(1);break;
 case 1:if(!secondCanvas.HasPage)throw new Exception("Two pages missing");Rotate(-1);rotateAll=false;ToggleEditing();break;
 case 2:if(!palette.TopLevel||!palette.Visible||editorDock.Visible)throw new Exception("Editor not floating");ShowPalette();BeginInline(null);inlineText.Text="Inline VinsPDF 0.27";textStyle.Ink=Color.DarkBlue;textStyle.Size=18;palette.SetStyle(textStyle);UpdateInlineFont();CommitInline();break;
 case 3:if(canvas.Selected==null)throw new Exception("Add text missing");var r=canvas.SelectionRect(canvas.Selected.Bounds);canvas.SetTool(0);canvas.TestDrag(new Point(r.Left+1,r.Top+1),new Point(r.Right+10,r.Bottom+10));if(editBusy)throw new Exception("Select mode moved item");if(canvas.Selection.Count==0)throw new Exception("Marquee over item failed");canvas.SetTool(1);var center=canvas.SelectionRect(canvas.CombinedSelection().Bounds);canvas.TestHover(new Point((center.Left+center.Right)/2,(center.Top+center.Bottom)/2));if(canvas.Cursor!=Cursors.Hand)throw new Exception("Centre cursor not a pointing hand");canvas.TestGesture(false,28,18);break;
 case 4:camera=canvas.PageRectangle;UndoEditor(false);break;
 case 5:if(camera!=canvas.PageRectangle)throw new Exception("Undo moved camera");canvas.Selected=canvas.Objects.First(o=>o.Text=="Inline VinsPDF 0.27");canvas.Selection.Clear();canvas.Selection.Add(canvas.Selected);canvas.RotationPreviewPath=Path.Combine(V027Directory,"rotation-preview.png");canvas.TestRotationHandle(45);break;
 case 6:if(!editorState.Objects.Any(o=>o.Text=="Inline VinsPDF 0.27"&&Math.Abs(Math.Abs(o.Angle)-45)<2))throw new Exception("Rotation failed");UndoEditor(false);break;
 case 7:var field=typeof(EditorPalette).GetField("gridShow",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);((CheckBox)field.GetValue(palette)).Checked=true;if(!canvas.GridVisible)throw new Exception("Grid not live");canvas.SetTool(2);int page=pageIndex;for(int i=0;i<150;i++)canvas.ScrollWheel(-120);if(pageIndex!=page)throw new Exception("Edit scroll changed page");canvas.Fit("page");ShowOverview();break;
 case 8:if(overview==null||overview.IsDisposed)throw new Exception("Overview missing");using(var b=new Bitmap(overview.Width,overview.Height)){overview.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(V027Directory,"overview.png"));}overview.Close();BeginInline(null);CancelInline();SaveTo(Path.Combine(V027Directory,"ui-edited.pdf"));break;
 case 9:if(dirty)throw new Exception("Save incomplete");Capture027("editor.png");var layout=(ToolStripDropDownButton)bar.Items[1];layout.ShowDropDown();using(var b=new Bitmap(layout.DropDown.Width,layout.DropDown.Height)){layout.DropDown.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(V027Directory,"layout-menu.png"));}layout.HideDropDown();if(shell==null)throw new Exception("No tab shell");shell.Open(Path.GetFullPath(currentPath));shell.Activate(this);break;
 case 10:shell.Detach();break;
 case 11:if(TopLevelControl==shell)throw new Exception("Detach failed");ShowPalette();BeginInline(null);CancelInline();Capture027("detached.png");Trace("PASS 027 floating panel/add text/repeated show, three modes, selection over item, movement/undo fixed camera, rotation, live grid, edit wheel lock, overview, tabs/detach, save");timer.Stop();timer.Dispose();WindowSession.Current.CloseAll();break;
 }}catch(Exception ex){Trace("FAIL 027 stage="+(stage-1)+" "+ex);timer.Stop();CancelInline();dirty=false;if(WindowSession.Current!=null)WindowSession.Current.CloseAll();else Close();}};timer.Start();}
 void Capture027(string name){Form window=TopLevelControl as Form??this;using(var image=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(V027Directory,name));}if(palette!=null)using(var b=new Bitmap(palette.Width,palette.Height)){palette.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(V027Directory,"palette.png"));}}
}
}
